export type CourseSlug = "core" | "intermediate" | "dom" | "practice" | "interview";

export interface Course {
  slug: CourseSlug;
  title: string;
  tagline: string[];
  description: string;
  color: string;
  topics: TopicMeta[];
}

export interface TopicMeta {
  slug: string;
  title: string;
  description: string;
  tags: string[];
  /** Number of challenges. Generated by `npm run gen:catalog`, verified by tests/content.test.ts. */
  count: number;
  /** Lightweight index of the topic's challenges, generated alongside `count` so pages need not load the topic. */
  challenges: ChallengeMeta[];
}

export interface ChallengeMeta {
  slug: string;
  title: string;
  difficulty: Difficulty;
}

export interface Topic extends Omit<TopicMeta, "challenges"> {
  course: CourseSlug;
  challenges: Challenge[];
}

/** 1 refresher · 2 solid · 3 interview-hard */
export type Difficulty = 1 | 2 | 3;
export type ChallengeKind = "implement" | "fix" | "complete" | "predict";

export interface TestCase {
  name: string;
  code: string;
}

export interface Challenge {
  slug: string;
  title: string;
  kind: ChallengeKind;
  difficulty: Difficulty;
  tags: string[];
  description: string;
  starter: string;
  solution: string;
  tests: TestCase[];
  hints?: string[];
  html?: string;
  timeoutMs?: number;
}

export const DEFAULT_TIMEOUT_MS = 3000;

export const challengeId = (course: string, topic: string, slug: string) => `${course}/${topic}/${slug}`;
